import{_ as a,o as n,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"System Overview","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/architecture/system-overview.md"},"headers":[],"relativePath":"sovereign-os/architecture/system-overview.md","filePath":"sovereign-os/architecture/system-overview.md"}'),s={name:"sovereign-os/architecture/system-overview.md"};function r(o,e,l,c,p,d){return n(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="system-overview" tabindex="-1">System Overview <a class="header-anchor" href="#system-overview" aria-label="Permalink to &quot;System Overview&quot;">​</a></h1><p><strong>Status:</strong> Draft<br><strong>Version:</strong> 0.1<br><strong>Scope:</strong> Long-term platform direction and Milestone 01.2 boundaries; not the active Phase 01 image architecture</p><blockquote><p>The active Phase 01 architecture is defined by <a href="./../adrs/0001-phase-01-appliance-architecture.html">ADR-0001</a> and <a href="./../rfcs/0010-raspberry-pi-image-deployment.html">RFC-0010</a>. Phase 01 does not implement the platform components described below.</p></blockquote><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Sovereign OS is a local application platform that presents independently managed home services through a coherent user experience. AI is one interface to this platform, not a privileged replacement for platform controls.</p><p>This document records known system boundaries and constraints. Exact technology, process, packaging, and protocol decisions require research and RFC approval.</p><h2 id="preview-context" tabindex="-1">Preview Context <a class="header-anchor" href="#preview-context" aria-label="Permalink to &quot;Preview Context&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Local browser</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>Web interface and local API</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>Core runtime</span></span>
<span class="line"><span>    +--&gt; health and configuration</span></span>
<span class="line"><span>    +--&gt; AI orchestration</span></span>
<span class="line"><span>    +--&gt; inference provider adapter --&gt; local model runner</span></span>
<span class="line"><span>    +--&gt; capability registry and executor</span></span>
<span class="line"><span>                 +--&gt; Pi-hole adapter --&gt; Pi-hole v6 API</span></span>
<span class="line"><span>                 +--&gt; web.search --&gt; local SearXNG --&gt; upstream engines</span></span>
<span class="line"><span>                 +--&gt; web.fetch --&gt; allowlisted external page</span></span></code></pre></div><p>The preview may package some boundaries together in one process. Logical boundaries should still be explicit so they can be tested and separated later if evidence requires it.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="web-interface" tabindex="-1">Web Interface <a class="header-anchor" href="#web-interface" aria-label="Permalink to &quot;Web Interface&quot;">​</a></h3><p>Provides onboarding, dashboard, chat, status, and minimum settings. It must render clear degraded states and must not contain Pi-hole credentials or provider secrets.</p><p>The first implementation is Sovereign Console at <code>/console/</code>. It is a dependency-free read-only health interface backed by <code>/api/v1/health</code>. Service interfaces such as Pi-hole remain independently namespaced.</p><h3 id="local-api" tabindex="-1">Local API <a class="header-anchor" href="#local-api" aria-label="Permalink to &quot;Local API&quot;">​</a></h3><p>Accepts requests from the web interface, enforces the preview access-control model, validates inputs, and returns structured results. Public internet access is outside preview scope.</p><p>The initial health service binds only to loopback, runs without root or Docker socket access, and reads bounded system interfaces plus appliance readiness records. Nginx exposes only its versioned health resource to the LAN.</p><h3 id="core-runtime" tabindex="-1">Core Runtime <a class="header-anchor" href="#core-runtime" aria-label="Permalink to &quot;Core Runtime&quot;">​</a></h3><p>Owns startup, configuration, health, structured logging, error handling, and coordination between platform components. The runtime should remain small during the preview.</p><h3 id="ai-orchestration" tabindex="-1">AI Orchestration <a class="header-anchor" href="#ai-orchestration" aria-label="Permalink to &quot;AI Orchestration&quot;">​</a></h3><p>Converts a user request into a proposal to invoke a registered capability. The model can select only capabilities provided in its current tool context. Model output is untrusted and must be validated before execution.</p><h3 id="capability-registry-and-executor" tabindex="-1">Capability Registry and Executor <a class="header-anchor" href="#capability-registry-and-executor" aria-label="Permalink to &quot;Capability Registry and Executor&quot;">​</a></h3><p>Maintains named operations and their typed contracts. It validates capability identity, input, permissions, side-effect classification, timeout, and output independently of the model.</p><h3 id="pi-hole-adapter" tabindex="-1">Pi-hole Adapter <a class="header-anchor" href="#pi-hole-adapter" aria-label="Permalink to &quot;Pi-hole Adapter&quot;">​</a></h3><p>Maps Pi-hole API operations into stable platform capabilities and error types. Preview operations are read-only and use the least privilege available from the supported Pi-hole API.</p><h3 id="ai-provider" tabindex="-1">AI Provider <a class="header-anchor" href="#ai-provider" aria-label="Permalink to &quot;AI Provider&quot;">​</a></h3><p>Supplies language-model inference through a provider-neutral contract owned by Sovereign. The initial direction is local inference, with llama.cpp and Ollama benchmarked behind the same adapter. Provider choice must not change conversation, model-management, or capability safety boundaries. The runner API binds only to a private host/container interface and is not a LAN API.</p><h3 id="model-manager" tabindex="-1">Model Manager <a class="header-anchor" href="#model-manager" aria-label="Permalink to &quot;Model Manager&quot;">​</a></h3><p>Owns model manifests, license/source metadata, digest verification, import, activation, compatibility, and storage under persistent Sovereign data. A runner-specific model catalog is an implementation convenience, not the source of product truth.</p><h3 id="web-search-adapter" tabindex="-1">Web Search Adapter <a class="header-anchor" href="#web-search-adapter" aria-label="Permalink to &quot;Web Search Adapter&quot;">​</a></h3><p>Maps the stable <code>web.search</code> capability to a locally operated SearXNG service. SearXNG is a replaceable provider, not a capability contract. Search queries still travel to configured upstream engines, so external communication must be explicit and private household context must not be silently added to queries.</p><p>Fetched pages are handled by a separate constrained <code>web.fetch</code> capability. Search does not grant the model general network access.</p><h2 id="request-flow" tabindex="-1">Request Flow <a class="header-anchor" href="#request-flow" aria-label="Permalink to &quot;Request Flow&quot;">​</a></h2><ol><li>The local user submits a question.</li><li>The API creates a bounded orchestration request containing only relevant capability descriptions.</li><li>The model either proposes a registered capability invocation or produces a non-tool response.</li><li>The executor treats the proposal as untrusted data.</li><li>The executor validates name, schema, permissions, limits, and preview side-effect policy.</li><li>The selected adapter invokes an allowlisted service operation.</li><li>The adapter returns bounded typed data, citations, or a typed error.</li><li>The system produces a user-facing explanation grounded in that result.</li><li>Diagnostics record the event without credentials or sensitive DNS details by default.</li></ol><h2 id="trust-boundaries" tabindex="-1">Trust Boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust Boundaries&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User/browser</span></span>
<span class="line"><span>    | authenticated or preview-controlled boundary</span></span>
<span class="line"><span>Core platform</span></span>
<span class="line"><span>    | untrusted model-output boundary</span></span>
<span class="line"><span>AI provider</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Core platform</span></span>
<span class="line"><span>    | credential and service API boundary</span></span>
<span class="line"><span>Pi-hole</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Core platform</span></span>
<span class="line"><span>    | external-query and untrusted-content boundary</span></span>
<span class="line"><span>SearXNG, upstream search engines, and fetched websites</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Core platform</span></span>
<span class="line"><span>    | package and lifecycle boundary (future)</span></span>
<span class="line"><span>Plugins</span></span></code></pre></div><ul><li>The browser is not trusted merely because it is on the local network.</li><li>Model output is always untrusted.</li><li>Pi-hole data may reveal household browsing patterns and is sensitive.</li><li>Search terms and fetched content cross an explicit external trust boundary; self-hosting SearXNG does not eliminate upstream disclosure.</li><li>Plugins will eventually be less trusted than the core platform; the preview must avoid designing implicit unlimited plugin authority.</li></ul><h2 id="data-categories" tabindex="-1">Data Categories <a class="header-anchor" href="#data-categories" aria-label="Permalink to &quot;Data Categories&quot;">​</a></h2><ul><li>Platform configuration</li><li>Authentication or preview access-control data</li><li>Pi-hole connection secret</li><li>Optional AI-provider secret</li><li>Conversation content</li><li>Search queries, result URLs, and fetched excerpts</li><li>Model artifacts, licenses, manifests, and activation state</li><li>Capability request and result metadata</li><li>Pi-hole statistics and client identifiers</li><li>Logs, metrics, and diagnostic data</li></ul><p>Handling details belong in the <a href="./../security/data-inventory.html">data inventory</a>.</p><h2 id="preview-constraints" tabindex="-1">Preview Constraints <a class="header-anchor" href="#preview-constraints" aria-label="Permalink to &quot;Preview Constraints&quot;">​</a></h2><ul><li>No arbitrary shell execution.</li><li>No direct Pi-hole database manipulation.</li><li>No Pi-hole write operations.</li><li>No public binding or remote access by default.</li><li>No secrets in source control, browser payloads, or normal logs.</li><li>No model call bypassing the capability executor.</li><li>No model runner exposed directly to the LAN.</li><li>No general network tool presented to the model.</li><li>No unsupported operation represented as successful.</li><li>No mandatory telemetry.</li></ul><h2 id="current-unknowns" tabindex="-1">Current Unknowns <a class="header-anchor" href="#current-unknowns" aria-label="Permalink to &quot;Current Unknowns&quot;">​</a></h2><ul><li>Runtime language and web framework</li><li>Process and package boundaries</li><li>Native versus container deployment</li><li>Initial local runner and model, pending Raspberry Pi benchmark</li><li>Authentication mechanism</li><li>Capability schema format and naming convention</li><li>Configuration and secret storage</li><li>Data directory layout</li><li>Local hostname mechanism</li><li>Pi-hole API compatibility boundary</li><li>Log and diagnostic retention</li><li>Search-provider configuration, safe-fetch policy, and query retention</li></ul><p>These unknowns should be resolved through research, RFC review, experiments, and ADRs rather than silently in implementation.</p>`,44)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
